static uint16_t tmp_idx = 0;

SlotInfo get_mapped_slot(SlotType type, uint16_t idx) {
    SlotInfo ret;
    ret.type = type;
    ret.idx = idx;
    if (ret.type == SUB_SLOT_TMPL) {
        assert(ret.idx < (1UL<<STACK_INDEX_SHIFT));
        if (tmpl_map[ret.idx] == 0xffff) {
            assert(tmp_idx < (1UL<<STACK_INDEX_SHIFT));
#ifdef DEBUG
            printf("register loc%d as %d\n", ret.idx, tmp_idx); fflush(NULL);
#endif
            tmpl_map[ret.idx] = tmp_idx;
            tmp_idx += 1;
        }
        ret.type = SUB_SLOT_TMP;
        ret.idx = tmpl_map[ret.idx];
        return ret;
    } else if (ret.type == SUB_SLOT_TMPT) {
        assert(ret.idx < (1UL<<STACK_INDEX_SHIFT));
        if (tmpt_map[ret.idx] == 0xffff) {
            assert(tmp_idx < (1UL<<STACK_INDEX_SHIFT));
#ifdef DEBUG
            printf("register tmp%d as %d\n", ret.idx, tmp_idx); fflush(NULL);
#endif
            tmpt_map[ret.idx] = tmp_idx;
            tmp_idx += 1;
        }
        ret.type = SUB_SLOT_TMP;
        ret.idx = tmpt_map[ret.idx];
        return ret;
    } else {
        return ret;
    }
}

OperandType get_original_slot_for_debug(OperandType tmp) {
    OperandType ret;
    ret.s.valid = 0;
    if (!(tmp.s.valid && tmp.s.slot_type == SUB_SLOT_TMP)) {
        return ret;
    }
    for (int i = 0; i < sizeof(tmpl_map)/sizeof(uint16_t); ++i) {
        if (tmpl_map[i] == tmp.s.slot_idx) {
            ret.s.valid = 1;
            ret.s.slot_type = SUB_SLOT_TMPL;
            ret.s.slot_idx = i;
            return ret;
        }
    }
    for (int i = 0; i < sizeof(tmpt_map)/sizeof(uint16_t); ++i) {
        if (tmpt_map[i] == tmp.s.slot_idx) {
            ret.s.valid = 1;
            ret.s.slot_type = SUB_SLOT_TMPT;
            ret.s.slot_idx = i;
            return ret;
        }
    }
    return ret;
}

void reset_tmp_mapping() {
    memset(tmpl_map, 0xff, sizeof(tmpl_map));
    memset(tmpt_map, 0xff, sizeof(tmpt_map));
    tmp_idx = 0;
}

XMMReg lookup_xmm_map(uint64_t offset) {
    uint16_t off = (uint16_t)offset;
    XMMReg x;
    x.xmm_idx = NON_XMM;
    x.xmm_offset = 0;
    if (xmm_offsets[0] <= off && off < (xmm_offsets[XMM_TMP_IDX - 1] + 0x20)) {
        uint16_t idx = (off - xmm_offsets[0]) / 0x40;
        uint16_t delta = (off - xmm_offsets[0]) % 0x40;
        if (delta < 0x10) {
            x.xmm_idx = idx * 2;
            x.xmm_offset = delta;
        } else if (delta < 0x20) {
            x.xmm_idx = idx * 2 + 1;
            x.xmm_offset = delta - 0x10;
        }
    } else if (xmm_offsets[XMM_TMP_IDX] <= off && off < (xmm_offsets[XMM_TMP_IDX] + 0x20)) {
        uint16_t idx = XMM_TMP_IDX;
        uint16_t delta = off - xmm_offsets[XMM_TMP_IDX];
        if (delta < 0x10) {
            x.xmm_idx = idx * 2;
            x.xmm_offset = delta;
        } else if (delta < 0x20) {
            x.xmm_idx = idx * 2 + 1;
            x.xmm_offset = delta - 0x10;
        }
    }
    return x;
}

/* Free a singly-linked list of UnifiedInstr (and their operand data). */
void free_instr_list(UnifiedInstr *head) {
    while (head) {
        UnifiedInstr *next = head->next;
        free(head);
        head = next;
    }
}

void op_list_init(OpList *l) {
    l->data = NULL;
    l->len = 0;
    l->cap = 0;
}

void op_list_add(OpList *l, Operand op) {
    if (l->len >= l->cap) {
        l->cap = l->cap ? l->cap * 2 : 8;
        l->data = realloc(l->data, l->cap * sizeof(Operand));
    }
    l->data[l->len++] = op;
}

void op_list_free(OpList *l) {
    free(l->data);
    l->data = NULL;
    l->len = l->cap = 0;
}

/* Append a UnifiedInstr to the context's list (O(1) using tail) */
void append_instr(TcgContext *ctx, UnifiedInstr *u) {
    u->next = NULL;
    if (ctx->instr_tail) {
        ctx->instr_tail->next = u;
        ctx->instr_tail = u;
    } else {
        ctx->instr_head = u;
        ctx->instr_tail = u;
    }
}

/*
 * Reset the instruction list in the context, freeing all allocated
 * UnifiedInstr nodes.  After this call, instr_head and instr_tail
 * are both NULL and the associated memory has been released.
 */
void tcg_context_reset_instrs(TcgContext *ctx) {
    free_instr_list(ctx->instr_head);
    ctx->instr_head = NULL;
    ctx->instr_tail = NULL;
}

